<?php
require_once __DIR__ . '/backend/auth.php';
$actual = exigirUsuario($conexion);
$tituloPagina = $tituloPagina ?? 'Inicio';
$menuRows = $conexion->execute_query('SELECT m.id_menu,m.id_menu_padre,m.nombre,m.ruta FROM menus m WHERE m.eliminado_en IS NULL AND m.activo=1 AND (m.visible_todos=1 OR EXISTS (SELECT 1 FROM menu_permiso mp JOIN permisos p ON p.id_permiso=mp.id_permiso JOIN rol_permiso rp ON rp.id_permiso=p.id_permiso JOIN roles r ON r.id_rol=rp.id_rol JOIN usuario_rol ur ON ur.id_rol=r.id_rol WHERE mp.id_menu=m.id_menu AND ur.id_usuario=? AND mp.eliminado_en IS NULL AND p.eliminado_en IS NULL AND p.activo=1 AND rp.eliminado_en IS NULL AND r.eliminado_en IS NULL AND r.activo=1 AND ur.eliminado_en IS NULL)) ORDER BY m.orden,m.id_menu', [(int)$actual['id_usuario']])->fetch_all(MYSQLI_ASSOC);
$menuIds = array_column($menuRows, null, 'id_menu');
$theme = !empty($actual['modo_oscuro']) ? 'dark' : 'light';
?>
<!doctype html><html lang="es" data-theme="<?= $theme ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?= htmlspecialchars(csrf()) ?>"><title><?= htmlspecialchars($tituloPagina) ?> | Salus Infirmorum</title><link rel="stylesheet" href="assets/app.css"></head><body>
<div class="app-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>Salus<br><small>Infirmorum</small></span></a><p class="nav-label">Navegación</p><nav class="nav-list">
<?php foreach ($menuRows as $m): if ($m['id_menu_padre'] && !isset($menuIds[$m['id_menu_padre']])) continue; if (!$m['ruta']) { echo '<span class="nav-group">'.htmlspecialchars($m['nombre']).'</span>'; continue; } $active = basename(parse_url($m['ruta'], PHP_URL_PATH) ?: '') === basename($_SERVER['SCRIPT_NAME']); ?>
<a class="nav-link<?= $active?' active':'' ?><?= $m['id_menu_padre']?' subnav':'' ?>" href="<?= htmlspecialchars($m['ruta']) ?>"><?= htmlspecialchars($m['nombre']) ?></a>
<?php endforeach; ?></nav><div class="sidebar-bottom"><a class="nav-link" href="perfil.php">Mi perfil</a><form method="post" action="logout.php"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf()) ?>"><button class="nav-link logout" type="submit">Cerrar sesión</button></form></div></aside>
